import{_ as t,o as a,c as n,ag as s}from"./chunks/framework.BpFM782D.js";const u=JSON.parse('{"title":"cicd-patterns","description":"","frontmatter":{},"headers":[],"relativePath":"skills/cicd-patterns.md","filePath":"skills/cicd-patterns.md"}'),r={name:"skills/cicd-patterns.md"};function o(i,e,l,d,c,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="cicd-patterns" tabindex="-1">cicd-patterns <a class="header-anchor" href="#cicd-patterns" aria-label="Permalink to &quot;cicd-patterns&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>cicd-patterns</td></tr><tr><td>說明</td><td>已驗證的 CI/CD 踩坑解法資料庫（非通用排查流程）。包含 Docker ARG/ENV 混淆、 .dockerignore glob 遞迴誤殺、container EACCES 權限錯誤、Next.js standalone HOSTNAME 綁定、CI 環境變數汙染測試、Runner tags 路由、cross-repo 靜態站部署 等 6 大 pattern 的精確修正方式。 當遇到以下具體症狀時，本 skill 能直接給出已驗證的解法，不需要從頭排查： 「API version mismatch」「EACCES permission denied .next/cache」 「NEXT_PUBLIC_* is not set（runtime）」「healthcheck unhealthy 但 logs 正常」 「本機 lint/test 通過但 CI 失敗」「Docker build OK 但內容頁空白」 「GitLab job pending 找不到 Runner」「.env 的 # 變成值」 「private repo 怎麼部署 GitHub Pages」「跨 repo 部署」「deploy key 設定」 「peaceiris/actions-gh-pages」「startup_failure」「.nojekyll」「base path 404」。 這不是通用 debug 工具，而是已知陷阱的快速匹配。任何 Docker + CI/CD 的問題 都建議先查本 skill 的 pattern 速查表，再決定是否需要更深入的排查。</td></tr><tr><td>來源目錄</td><td><code>skills/cicd-patterns/</code></td></tr></tbody></table><hr><h1 id="ci-cd-patterns-—-踩坑診斷-skill" tabindex="-1">CI/CD Patterns — 踩坑診斷 Skill <a class="header-anchor" href="#ci-cd-patterns-—-踩坑診斷-skill" aria-label="Permalink to &quot;CI/CD Patterns — 踩坑診斷 Skill&quot;">​</a></h1><p>從實戰中萃取的 6 個 CI/CD 通用 pattern。這些 pattern 不限定特定框架或 CI 平台， 適用於任何使用 Docker + CI/CD 的專案。</p><hr><h2 id="pattern-速查表" tabindex="-1">Pattern 速查表 <a class="header-anchor" href="#pattern-速查表" aria-label="Permalink to &quot;Pattern 速查表&quot;">​</a></h2><p>根據你看到的<strong>症狀</strong>，快速定位可能的 pattern：</p><table tabindex="0"><thead><tr><th>#</th><th>Pattern</th><th>典型症狀</th><th>參考文件</th></tr></thead><tbody><tr><td>1</td><td>Build vs Runtime 混淆</td><td>環境變數 runtime 讀不到、API 版本不相容、container hostname 異常</td><td><code>references/pattern-build-vs-runtime.md</code></td></tr><tr><td>2</td><td>本機 vs CI 不一致</td><td>本機 OK 但 CI 失敗、CI 多出額外錯誤、測試結果不同</td><td><code>references/pattern-local-vs-ci.md</code></td></tr><tr><td>3</td><td>Glob 行為差異</td><td>檔案被意外排除、build 成功但內容消失、ignore 規則行為不如預期</td><td><code>references/pattern-glob-behaviors.md</code></td></tr><tr><td>4</td><td>容器非 Root 權限</td><td>EACCES 權限錯誤、cache 寫入失敗、image optimization 失敗</td><td><code>references/pattern-container-permissions.md</code></td></tr><tr><td>5</td><td>多 Runner 路由</td><td>Job pending 找不到 Runner、Job 跑在錯誤的環境</td><td><code>references/pattern-runner-routing.md</code></td></tr><tr><td>6</td><td>Cross-Repo 靜態站部署</td><td>Private repo 無法用 Pages、deploy key 設定、base path 404、<code>.nojekyll</code> 缺失</td><td><code>references/pattern-cross-repo-deploy.md</code></td></tr></tbody></table><hr><h2 id="診斷決策樹" tabindex="-1">診斷決策樹 <a class="header-anchor" href="#診斷決策樹" aria-label="Permalink to &quot;診斷決策樹&quot;">​</a></h2><p>遇到 CI/CD 問題時，按以下順序排查：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>問題發生在哪個階段？</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ Build 階段失敗</span></span>
<span class="line"><span>│  ├─ Docker build 失敗 → 檢查 Pattern 1（版本相容性）</span></span>
<span class="line"><span>│  ├─ Lint / Test 失敗 → 檢查 Pattern 2（環境差異）</span></span>
<span class="line"><span>│  └─ Build 成功但產物不完整 → 檢查 Pattern 3（Glob 排除）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ Runtime 階段異常</span></span>
<span class="line"><span>│  ├─ 環境變數缺失 → 檢查 Pattern 1（ARG vs ENV）</span></span>
<span class="line"><span>│  ├─ 權限錯誤 (EACCES) → 檢查 Pattern 4（非 Root 權限）</span></span>
<span class="line"><span>│  └─ Healthcheck 失敗 → 檢查 Pattern 1（hostname 綁定）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ Job 排程問題</span></span>
<span class="line"><span>│  └─ Job pending / 路由錯誤 → 檢查 Pattern 5（Runner 路由）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ Deploy / Pages 問題</span></span>
<span class="line"><span>│  ├─ Private repo 無法啟用 Pages → 檢查 Pattern 6（Cross-Repo 部署）</span></span>
<span class="line"><span>│  ├─ 部署成功但頁面空白或 404 → 檢查 Pattern 6（base path / .nojekyll）</span></span>
<span class="line"><span>│  └─ startup_failure → 檢查 Pattern 6（billing / permissions / syntax）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└─ 本機和 CI 結果不同</span></span>
<span class="line"><span>   └─ 直接檢查 Pattern 2（環境隔離）</span></span></code></pre></div><hr><h2 id="預防-checklist" tabindex="-1">預防 Checklist <a class="header-anchor" href="#預防-checklist" aria-label="Permalink to &quot;預防 Checklist&quot;">​</a></h2><p>在設定或修改 CI/CD 配置前，逐項檢查：</p><h3 id="docker-相關" tabindex="-1">Docker 相關 <a class="header-anchor" href="#docker-相關" aria-label="Permalink to &quot;Docker 相關&quot;">​</a></h3><ul><li>[ ] CI 的 Docker image 版本 &gt;= host Docker daemon 的最低 API 要求</li><li>[ ] Dockerfile 中 build-time 需要的值用 <code>ARG</code>，runtime 需要的值用 <code>ENV</code></li><li>[ ] 非 root 使用者有寫入 cache/log/upload 目錄的權限</li><li>[ ] Container 服務綁定 <code>0.0.0.0</code>（非 localhost 或 container ID）</li><li>[ ] <code>.dockerignore</code> 排除規則不會誤殺必要檔案（特別注意 <code>*.ext</code> 的遞迴匹配）</li></ul><h3 id="環境變數相關" tabindex="-1">環境變數相關 <a class="header-anchor" href="#環境變數相關" aria-label="Permalink to &quot;環境變數相關&quot;">​</a></h3><ul><li>[ ] CI Protected Variables 不會汙染 test job</li><li>[ ] 測試自行控制環境變數，不依賴外部環境狀態</li><li>[ ] <code>.env</code> 檔案中 <code>=</code> 後的 <code>#</code> 不是註解（需獨立一行）</li><li>[ ] <code>--env-file</code>（CLI）和 <code>env_file</code>（compose directive）用途不同，確認都有設定</li></ul><h3 id="lint-test-相關" tabindex="-1">Lint / Test 相關 <a class="header-anchor" href="#lint-test-相關" aria-label="Permalink to &quot;Lint / Test 相關&quot;">​</a></h3><ul><li>[ ] Commit 前本機跑過 <code>lint</code> + <code>test</code></li><li>[ ] 第三方元件（如 shadcn/ui）安裝後立即處理 lint 相容性</li><li>[ ] 正則表達式無超線性回溯風險（<code>(.+)</code> → <code>([^\\n]+)</code>）</li></ul><h3 id="runner-相關" tabindex="-1">Runner 相關 <a class="header-anchor" href="#runner-相關" aria-label="Permalink to &quot;Runner 相關&quot;">​</a></h3><ul><li>[ ] 每個 job 的 tags 精確匹配目標 Runner</li><li>[ ] 需要 Node 環境的 job 和需要 Docker socket 的 job 使用不同 tags</li></ul><h3 id="cross-repo-部署相關" tabindex="-1">Cross-Repo 部署相關 <a class="header-anchor" href="#cross-repo-部署相關" aria-label="Permalink to &quot;Cross-Repo 部署相關&quot;">​</a></h3><ul><li>[ ] Deploy key 使用 Ed25519，目標 repo 勾選 write access</li><li>[ ] Private key 存為來源 repo 的 Actions secret，名稱與 workflow 一致</li><li>[ ] 靜態站的 <code>base</code> path 對應目標 repo 名稱（或自訂域名時設為 <code>/</code>）</li><li>[ ] <code>publish_dir</code> 指向正確的建置輸出目錄</li><li>[ ] 目標 repo 的 Pages source 設為 <code>gh-pages</code> branch</li></ul><hr><h2 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h2><ol><li><strong>遇到問題時</strong>：先看速查表，根據症狀找到可能的 pattern</li><li><strong>讀取對應 reference</strong>：每個 pattern 都有具體案例和通用解法</li><li><strong>套用預防 checklist</strong>：修復後用 checklist 確認不會再犯</li><li><strong>記錄新案例</strong>：如果是新的 pattern，建議回饋到 <code>docs/cicd-troubleshooting.md</code></li></ol><hr><h2 id="來源" tabindex="-1">來源 <a class="header-anchor" href="#來源" aria-label="Permalink to &quot;來源&quot;">​</a></h2><ul><li>Pattern 1–5 萃取自 <code>frontstage-web/docs/cicd-troubleshooting.md</code>（2026-03-09）， 涵蓋 GitLab CI + Docker + Next.js standalone 架構的 8 個實戰踩坑。</li><li>Pattern 6 萃取自 <code>team-claude-config</code> VitePress 文件站跨 repo 部署實戰（2026-03-21）， 涵蓋 GitHub Actions + Deploy Key + GitHub Pages 的完整流程。</li><li>所有 pattern 已泛化為通用模式，不限定特定框架。</li></ul>`,32)])])}const b=t(r,[["render",o]]);export{u as __pageData,b as default};
